CREATE TABLE IF NOT EXISTS campus_state (
  id smallint PRIMARY KEY CHECK (id = 1),
  payload jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Domain schema for the normalized production records. UUIDs are generated by
-- the application so Supabase does not require extensions or elevated rights.
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS academic_years (id uuid PRIMARY KEY, label text NOT NULL UNIQUE, starts_on date NOT NULL, ends_on date NOT NULL, CHECK (ends_on > starts_on));
CREATE TABLE IF NOT EXISTS semesters (id uuid PRIMARY KEY, academic_year_id uuid NOT NULL REFERENCES academic_years(id), name text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, UNIQUE (academic_year_id,name), CHECK (ends_on > starts_on));
CREATE TABLE IF NOT EXISTS management_users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, full_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS teachers (id uuid PRIMARY KEY, department_id uuid NOT NULL REFERENCES departments(id), email text NOT NULL UNIQUE, full_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id uuid PRIMARY KEY, student_number text NOT NULL UNIQUE, email text NOT NULL UNIQUE, full_name text NOT NULL, department_id uuid NOT NULL REFERENCES departments(id), password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS courses (id uuid PRIMARY KEY, department_id uuid NOT NULL REFERENCES departments(id), code text NOT NULL UNIQUE, title text NOT NULL, credits smallint NOT NULL CHECK (credits > 0));
CREATE TABLE IF NOT EXISTS classes (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), semester_id uuid NOT NULL REFERENCES semesters(id), class_name text NOT NULL, section text NOT NULL, UNIQUE(course_id,semester_id,class_name,section));
CREATE TABLE IF NOT EXISTS student_enrollments (student_id uuid NOT NULL REFERENCES students(id), class_id uuid NOT NULL REFERENCES classes(id), enrolled_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(student_id,class_id));
CREATE TABLE IF NOT EXISTS teacher_course_assignments (teacher_id uuid NOT NULL REFERENCES teachers(id), class_id uuid NOT NULL REFERENCES classes(id), PRIMARY KEY(teacher_id,class_id));
CREATE TABLE IF NOT EXISTS attendance_sessions (id uuid PRIMARY KEY, teacher_id uuid NOT NULL REFERENCES teachers(id), course_id uuid NOT NULL REFERENCES courses(id), class_id uuid NOT NULL REFERENCES classes(id), session_date date NOT NULL, starts_at time NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(class_id,session_date,starts_at));
CREATE TABLE IF NOT EXISTS attendance_records (session_id uuid NOT NULL REFERENCES attendance_sessions(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id), status text NOT NULL CHECK(status IN ('present','absent')), remarks text, PRIMARY KEY(session_id,student_id));
CREATE INDEX IF NOT EXISTS attendance_records_student_idx ON attendance_records(student_id,session_id);
CREATE TABLE IF NOT EXISTS subject_marks (id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students(id), course_id uuid NOT NULL REFERENCES courses(id), semester_id uuid NOT NULL REFERENCES semesters(id), assessment text NOT NULL, marks numeric(6,2) NOT NULL CHECK(marks >= 0), maximum numeric(6,2) NOT NULL CHECK(maximum > 0 AND marks <= maximum), grade text, UNIQUE(student_id,course_id,semester_id,assessment));
CREATE TABLE IF NOT EXISTS semester_results (student_id uuid NOT NULL REFERENCES students(id), semester_id uuid NOT NULL REFERENCES semesters(id), sgpa numeric(4,2) NOT NULL CHECK(sgpa BETWEEN 0 AND 10), published_at timestamptz, PRIMARY KEY(student_id,semester_id));
CREATE TABLE IF NOT EXISTS fee_structures (id uuid PRIMARY KEY, semester_id uuid NOT NULL REFERENCES semesters(id), department_id uuid REFERENCES departments(id), category text NOT NULL CHECK(category IN ('tuition','examination','library','other')), amount numeric(12,2) NOT NULL CHECK(amount >= 0), due_date date NOT NULL);
CREATE TABLE IF NOT EXISTS student_fee_records (id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students(id), fee_structure_id uuid NOT NULL REFERENCES fee_structures(id), amount_due numeric(12,2) NOT NULL CHECK(amount_due >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,fee_structure_id));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY, fee_record_id uuid NOT NULL REFERENCES student_fee_records(id), amount numeric(12,2) NOT NULL CHECK(amount > 0), reference text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('recorded','voided')), recorded_by uuid NOT NULL REFERENCES management_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payments_fee_record_idx ON payments(fee_record_id,created_at);
CREATE TABLE IF NOT EXISTS books (id uuid PRIMARY KEY, isbn text UNIQUE, title text NOT NULL, author text NOT NULL, publisher text, category text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS book_copies (id uuid PRIMARY KEY, book_id uuid NOT NULL REFERENCES books(id), barcode text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('available','issued','maintenance')));
CREATE TABLE IF NOT EXISTS library_issues (id uuid PRIMARY KEY, copy_id uuid NOT NULL REFERENCES book_copies(id), student_id uuid NOT NULL REFERENCES students(id), issued_by uuid NOT NULL REFERENCES management_users(id), issued_at date NOT NULL, due_at date NOT NULL, returned_at date, CHECK(due_at >= issued_at), CHECK(returned_at IS NULL OR returned_at >= issued_at));
CREATE UNIQUE INDEX IF NOT EXISTS library_one_active_issue_per_copy ON library_issues(copy_id) WHERE returned_at IS NULL;
CREATE INDEX IF NOT EXISTS library_student_history_idx ON library_issues(student_id,issued_at DESC);
